impl Solution {
    pub fn delete_middle(head: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
        let mut slow = 0;
        let mut fast = head.as_ref();

        while let Some(node) = fast {
            if node.next.is_none() {
                break;
            }
            slow += 1;
            fast = node.next.as_ref().unwrap().next.as_ref();
        }

        let mut dummy = Some(Box::new(ListNode { val: 0, next: head }));
        let mut cur = dummy.as_mut();

        for _ in 0..slow {
            cur = cur.unwrap().next.as_mut();
        }

        let node = cur.unwrap();
        node.next = node.next.as_mut().unwrap().next.take();

        dummy.unwrap().next
    }
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* deleteMiddle(ListNode* head) {

        if(head == NULL or head -> next == NULL)
            return NULL;

        ListNode* slow = head;
        ListNode* fast = head;
        ListNode* temp;

        while(true){

            temp = slow;
            slow = slow -> next;
            fast = fast -> next -> next;
            if(fast == NULL or fast -> next == NULL)
                break;

        }

        temp -> next = slow -> next;

        return head;
    }
};

class Solution {
public:
    ListNode* deleteMiddle(ListNode* head) {
        // Edge case: return None if there is only one node
        if (head -> next == nullptr)
            return nullptr;

        int count = 0;
        ListNode *p1 = head, *p2 = head;

        // First pass, count the number of nodes in the linked list using 'p1'.
        while (p1 != nullptr) {
            count++;
            p1 = p1 -> next;
        }

        // Get the index of the node to be deleted.
        int middleIndex = count / 2;

        // Second pass, let 'p2' move toward the predecessor of the middle node.
        for (int i = 0; i < middleIndex - 1; ++i)
            p2 = p2 -> next;

        // Delete the middle node and return 'head'.
        p2 -> next = p2 -> next -> next;
        return head;
    }
};

